scheduledSelect:
(product: ShopifyProduct, imageUrl: string) => {
    const targetBlock = blocks.find(b => b.id === shopifyTargetBlockId);
    if (!targetBlock) return;
    const n: any = product.node;
    const linkProduct: VipLinkProduct = {
      source: 'shopify', shopify_product_id: n.id, title: n.title,
      price: n.priceRange?.minVariantPrice?.amount ?? null, image_url: imageUrl || null,
    };
    if (shopifyForLink) {
      updateBlock(targetBlock.id, { ...targetBlock, vipLinkMode: 'product', vipLinkProduct: linkProduct });
      setShowShopifyPicker(false);
      setShopifyForLink(false);
      toast.success("Produto vinculado ao link!");
      return;
    }

    if (shopifySendMode === 'photo_only') {
      if (targetBlock.type === 'image') {
        updateBlock(targetBlock.id, appendDraftMedia({ ...targetBlock, mediaBrief: n.title, vipLinkProduct: targetBlock.vipLinkProduct || linkProduct }, [{ url: imageUrl, caption: '' }]));
      } else if (targetBlock.type === 'text') {
        // Add a new image block
        const nb = createBlock('image');
        nb.mediaItems = [{ url: imageUrl, caption: '' }];
        nb.mediaBrief = n.title;
        nb.vipLinkProduct = linkProduct;
        setBlocks(prev => [...prev, nb]);
      }
    } else {
      const handle = product.node.handle;
      const link = getOfficialProductUrl(handle);
      if (!link) { toast.error("Produto sem endereço válido no site oficial"); return; }
      if (targetBlock.type === 'text') {
        updateBlock(targetBlock.id, { ...targetBlock, content: targetBlock.content ? `${targetBlock.content}\n${link}` : link });
      }
    }
    setShowShopifyPicker(false);
    toast.success(shopifySendMode === 'photo_only' ? "Foto adicionada!" : "Link inserido!");
  }

posPayment:
async (gateway: Gateway) => {
    setGenerating(true);
    setGeneratedLink(""); setSplitDesc("");

    try {
      let link = "";

      if (gateway === "delivery" || gateway === "pickup") {
        link = "";
      } else if (gateway === "yampi") {
        const items = cart.map(c => ({
          sku: c.sku,
          shopify_variant_id: c.variantId,
          quantity: c.quantity,
          price: c.price,
        }));
        const { data, error } = await supabase.functions.invoke("yampi-create-payment-link", {
          body: {
            items,
            customer: linkedCustomer?.name || linkedCustomer?.whatsapp ? { name: linkedCustomer.name, phone: linkedCustomer.whatsapp } : undefined,
            ...(couponCode && { coupon_code: couponCode }),
          },
        });
        if (error || !data?.success) throw new Error(data?.error || error?.message || "Erro Yampi");
        link = data.payment_link;
      } else if (gateway === "store-checkout") {
        // Store checkout: save sale first, then generate link
        // Sale will be saved below in the common flow, so we generate a placeholder
        link = "__STORE_CHECKOUT__";
      } else if (gateway === "paypal") {
        // Create CRM order first, then create PayPal order from it
        const orderId = await ensureCrmOrder();
        if (!orderId) throw new Error("Erro ao criar pedido para PayPal");
        const { data, error } = await supabase.functions.invoke("paypal-create-order", {
          body: { orderId },
        });
        if (error || !data?.approvalUrl) throw new Error(data?.error || "Erro PayPal");
        link = data.approvalUrl;
      } else if (gateway === "pix") {
        // PIX requires orderId — sale will be created first below, then PIX generated
        link = "__PIX_PENDING__";
      }

      if (gateway !== "delivery" && gateway !== "pickup" && gateway !== "store-checkout" && gateway !== "pix" && !link) throw new Error("Link não gerado");

      // For store-checkout and pix, we need to save the sale first and then generate the link
      if (gateway !== "store-checkout" && gateway !== "pix") {
        setGeneratedLink(link || "DELIVERY_CONFIRMED");
      }
      if (gateway === "delivery") setDeliveryConfirmed(true);
      if (gateway === "pickup") setDeliveryConfirmed(true);

      // Save sale to pos_sales
      const sellerObj = sellers.find(s => s.id === selectedSeller);
      const paymentGw = gateway === "delivery" ? `delivery_${deliveryMethod}` : gateway;
      const saleStoreId = gateway === "pickup" ? pickupStoreId : storeId;
      const salePayload = {
        store_id: saleStoreId,
        seller_id: selectedSeller,
        customer_id: linkedCustomer?.id || null,
        subtotal: cartSubtotal,
        discount: discountAmount > 0 ? discountAmount : 0,
        total: orderTotal,
        status: gateway === "pickup" ? "pending_pickup" : "online_pending",
        sale_type: gateway === "pickup" ? "pickup" : "online",
        payment_gateway: paymentGw,
        payment_link: (gateway === "delivery" || gateway === "pickup" || gateway === "store-checkout") ? null : link,
        stock_source_store_id: stockStore,
        payment_method_detail: gateway === "delivery" ? deliveryMethod : null,
        payment_details: {
          link_origin: "online_hub",
          seller_name: sellerObj?.name || "",
          customer_name: linkedCustomer?.name || null,
          customer_phone: linkedCustomer?.whatsapp || null,
          customer_email: linkedCustomer?.email || null,
          original_subtotal: cartSubtotal,
          discount_amount: discountAmount,
          discount_type: discountType,
          discount_value: discountValue,
          shipping_amount: shippingAmount,
          free_shipping: Number(shippingAmount || 0) === 0,
          has_gift: hasGift,
          gift_description: hasGift ? giftDescription : null,
          net_product_total: cartTotal,
          items_detail: cart.map(c => ({
            title: c.title,
            variant: c.variantLabel,
            unit_price: c.price,
            compare_at_price: c.compareAtPrice,
            quantity: c.quantity,
          })),
          ...(gateway === "store-checkout" ? buildLinkInstallmentRule({
            maxInstallments: checkoutMaxInstallments,
            noInterestInstallments: checkoutNoInterestInstallments,
            interestRate: checkoutInterestRate,
            source: "pos_online_hub",
          }) : {}),

        },
        notes: deliveryNotes || null,
      };

      const { data: sale, error: saleErr } = await supabase
        .from("pos_sales")
        .insert(salePayload as any)
        .select("id")
        .single();

      if (saleErr || !sale) {
        throw new Error(saleErr?.message || "Não foi possível salvar a venda");
      }

      // Save sale items
      const saleItems = cart.map(c => ({
        sale_id: sale.id,
        sku: c.sku || null,
        barcode: null,
        product_name: c.title,
        variant_name: c.variantLabel || null,
        unit_price: c.price,
        quantity: c.quantity,
        total_price: c.price * c.quantity,
      }));

      const { error: saleItemsErr } = await supabase.from("pos_sale_items").insert(saleItems as any);
      if (saleItemsErr) {
        throw new Error(saleItemsErr.message || "Não foi possível salvar os itens da venda");
      }

      // For store-checkout, generate the link using the sale ID
      if (gateway === "store-checkout" && sale) {
        if (splitParts.length > 0) {
          const { data: splitData, error: splitError } = await supabase.functions.invoke("split-payment", {
            body: { action: "setup", saleId: sale.id, total: orderTotal, parts: splitParts },
          });
          if (splitError || splitData?.error) throw new Error(splitData?.error || splitError?.message || "Erro ao salvar divisão do pagamento");
        }
        const storeCheckoutLink = `https://checkout.bananacalcados.com.br/checkout-loja/${storeId}/${sale.id}`;
        setGeneratedLink(storeCheckoutLink);
        setShowLinkDialog(true);
      }

      // For PIX, now that we have the sale ID, generate the PIX
      if (gateway === "pix" && sale) {
        const { data: pixData, error: pixErr } = await supabase.functions.invoke("mercadopago-create-pix", {
          body: { orderId: sale.id },
        });
        if (pixErr || !pixData?.qrCode) throw new Error(pixData?.error || "Erro ao gerar PIX");
        const pixLink = pixData.ticketUrl || pixData.qrCode || "";
        setGeneratedLink(pixLink);
        setShowLinkDialog(true);
      }

      // Tiny order creation is now MANUAL ONLY (via the "Enviar/Reenviar ao Tiny" button).
      // The online sale is already saved locally above; no automatic Tiny push.

      // Transferência de estoque para Site desativada: venda online baixa direto da Loja Pérola no banco.

      toast.success(gateway === "pickup" ? "Retirada na loja registrada!" : gateway === "delivery" ? "Venda registrada!" : "Link gerado com sucesso!");
    } catch (e: any) {
      console.error("Generate link error:", e);
      toast.error(e.message || "Erro ao gerar link");
    } finally {
      setGenerating(false);
    }
  }

catalogVariants:
function variantsFromShopify(p: ShopifyProduct): CatalogVariant[] {
  return p.node.variants.edges.map(({ node: v }) => ({
    variant_id: v.id,
    sku: v.sku || null,
    title: v.title === "Default Title" ? "Único" : v.title,
    size: v.selectedOptions?.find((o) => SIZE_RX.test(o.name))?.value ?? null,
    color: v.selectedOptions?.find((o) => COLOR_RX.test(o.name))?.value ?? null,
    price: parseFloat(v.price.amount),
    image: v.image?.url ?? p.node.images.edges[0]?.node.url ?? null,
    enabled: true,
  }));
}

promotionSearch:
async () => {
    const term = q.trim();
    if (term.length < 2) return;
    setSearching(true);
    try {
      const m = term.match(CODE_RE);
      if (m) {
        const code = `${m[1].toUpperCase()}${m[2]}`;
        const { data: rows } = await db.from("v_product_color_codes").select("master_id, product_name").eq("code", code).limit(1);
        const mid = rows?.[0]?.master_id;
        if (mid) {
          const { data: master } = await db.from("products_master").select("shopify_product_id").eq("id", mid).maybeSingle();
          const pid = numId(master?.shopify_product_id);
          if (pid) { setResults([{ id: pid, title: `${code} · ${rows[0].product_name}` }]); return; }
          toast.warning(`${code}: produto sem vínculo com a Shopify`);
        }
        setResults([]); return;
      }
      const ps = await fetchProducts(20, `title:*${term}*`);
      setResults(ps.map((p) => ({ id: numId(p.node.id), title: p.node.title })));
    } catch (e: any) { toast.error(e?.message || "Erro na busca"); } finally { setSearching(false); }
  }
